  'Ces chiffres sont réservés à la direction et aux personnes qui règlent les factures. Demandez à votre consultant le droit « Régler les factures ».': 'These figures are reserved for management and for people who pay invoices. Ask your consultant for the “Pay invoices” right.',
  "La comptabilité n'est pas encore activée sur la base de données.": 'Accounting is not yet enabled in the database.',
  "Les achats et les marges se lisent déjà ; la saisie du chiffre d'affaires, les charges fixes, les salaires et la banque arriveront avec elle.": 'Purchases and margins can already be read; revenue entry, fixed costs, salaries and the bank will come with it.',
  "La comptabilité de l'app prépare vos chiffres et vos pièces pour la fiduciaire. Elle ne tient pas les comptes et n'établit ni le décompte TVA officiel ni les salaires.": 'The app’s accounting prepares your figures and documents for your accountant. It does not keep the books and produces neither the official VAT return nor payroll.',
  "Aucun inventaire validé : la période d'inventaire commence au premier inventaire validé.": 'No validated inventory: the inventory period starts at the first validated inventory.',
  'Montants TVA comprise, comme sur le ticket de caisse du soir.': 'Amounts incl. VAT, as on the evening till receipt.',
  'La caisse a enregistré': 'The till recorded',
  'ce jour-là. Une saisie ici la remplace pour ce jour.': 'that day. An entry here replaces it for that day.',
  "Seule une personne qui règle les factures peut saisir le chiffre d'affaires.": 'Only someone who pays invoices can enter revenue.',
  "Une charge fixe se saisit une fois : l'app la répartit sur chaque mois. N'importez pas aussi sa facture dans Factures & achats, sinon elle compte deux fois.": 'A fixed cost is entered once: the app spreads it over each month. Do not also import its invoice in Invoices & purchases, or it counts twice.',
