  'Taux de TVA par catégorie': 'VAT rate by category',
  "Sur place, le taux de la catégorie s'applique. Quand un ticket est marqué à emporter, seules les catégories cochées passent au taux réduit ; l'alcool reste toujours au taux normal. Le taux est figé sur chaque ligne à l'encaissement.": 'On site, the category rate applies. When a ticket is marked takeaway, only the ticked categories move to the reduced rate; alcohol always stays at the standard rate. The rate is frozen on each line at payment.',
  'Taux réduit à emporter': 'Reduced rate for takeaway',
  'Un article libre, ou un produit hors de ces catégories, reste au taux normal, à emporter compris.': 'A free item, or a product outside these categories, stays at the standard rate, takeaway included.',
  'Arrondir aux 5 centimes': 'Round to 5 centimes',
  'Au centime': 'To the centime',
  "L'arrondi ne porte que sur la part payée en espèces. L'écart est enregistré à part sur chaque ticket et repris dans la clôture.": 'Rounding only applies to the part paid in cash. The difference is recorded separately on each ticket and carried into the closing.',
  'La journée de caisse finit à': 'The till day ends at',
