  // Caisse v9 : terminal de paiement relié.
  'Terminal de paiement': 'Payment terminal',
  'Au tap sur « Carte », la caisse envoie le montant au terminal ; le client paie sur le terminal ; la caisse reçoit « accepté » ou « refusé » et pose le paiement toute seule.': 'On tapping "Card", the till sends the amount to the terminal; the guest pays on the terminal; the till receives "accepted" or "declined" and records the payment by itself.',
  "La caisse ne voit jamais une carte : ni numéro, ni date, ni code. Elle garde seulement le résultat (marque, quatre derniers chiffres, code d'autorisation). L'argent va du prestataire à la maison, sans passer par l'app.": 'The till never sees a card: no number, no date, no code. It only keeps the result (brand, last four digits, authorisation code). The money goes from the provider to the house, never through the app.',
  'Terminaux reliés': 'Linked terminals',
  "Les terminaux n'ont pas pu être lus. Fermez les Réglages et rouvrez-les.": 'The terminals could not be read. Close the Settings and open them again.',
  "Aucun terminal relié : les cartes s'encaissent à la main, comme aujourd'hui.": 'No linked terminal: cards are recorded by hand, as today.',
  'Terminal simulé': 'Simulated terminal',
  'n° de série': 'serial no.',
  'Clé enregistrée, se termine par': 'Key saved, ends with',
  'Clé enregistrée': 'Key saved',
  'Relié le': 'Linked on',
  'Il ne sert que les tickets du mode test : aucun argent ne bouge, aucun vrai ticket ne peut être payé par lui.': 'It only serves test-mode tickets: no money moves, and no real ticket can be paid through it.',
  'Ce terminal a déjà encaissé un paiement réel accepté.': 'This terminal has already taken a real accepted payment.',
  "Ce terminal n'a pas encore encaissé de paiement réel accepté : faites un premier paiement de 1 franc avant le service.": 'This terminal has not yet taken a real accepted payment: make a first 1-franc payment before service.',
  'Garder': 'Keep',
  'Retirer ce terminal': 'Remove this terminal',
  'Terminaux retirés :': 'Removed terminals:',
  'Leurs paiements passés restent dans la caisse ; un remboursement se fait alors chez le prestataire.': 'Their past payments stay in the till; a refund is then made with the provider.',
  'Relier un terminal': 'Link a terminal',
  'Prestataire': 'Provider',
  'Clé': 'Key',
  'Jumelage': 'Pairing',
  "Aucun prestataire réel n'est encore proposé. Le terminal simulé sert à s'entraîner en mode test ; un vrai terminal sera ajouté quand son prestataire aura confirmé ses règles et fourni un moyen d'essai sans argent réel.": 'No real provider is offered yet. The simulated terminal is for practising in test mode; a real terminal will be added once its provider has confirmed its rules and supplied a way to test without real money.',
  "Nom du terminal, tel que l'équipe le verra": 'Terminal name, as the team will see it',
  'Terminal du bar': 'Bar terminal',
  'Numéro de série, lu sous le terminal': 'Serial number, read under the terminal',
  'Saisie masquée': 'Hidden entry',
  "La clé part une seule fois vers le serveur, qui la range dans son coffre. Elle ne revient jamais à l'écran : seuls ses quatre derniers caractères seront rappelés.": 'The key is sent once to the server, which stores it in its vault. It never comes back to the screen: only its last four characters will be shown.',
  'Code de jumelage': 'Pairing code',
  'Code lu sur le terminal': 'Code read on the terminal',
  "Le code s'affiche sur le terminal et ne sert qu'une fois : il prouve que le terminal est devant vous.": 'The code is shown on the terminal and works only once: it proves the terminal is in front of you.',
  'Relier ce terminal': 'Link this terminal',
  'Relier ou retirer un terminal : consultant ou patron de la maison.': 'Linking or removing a terminal: consultant or owner of the house.',
  "Plafond d'un paiement sur le terminal, en CHF": 'Ceiling for one payment on the terminal, in CHF',
  "Au-dessus de ce montant, pourboire compris, la caisse n'envoie rien au terminal : une erreur de saisie ne part pas en débit.": 'Above this amount, tip included, the till sends nothing to the terminal: a typing error does not become a charge.',
  'Terminal relié': 'Terminal linked',
  'Terminal retiré': 'Terminal removed',
  'Étapes pour relier un terminal': 'Steps to link a terminal',
  "Aucun appareil, aucun argent : pour s'entraîner en mode test.": 'No device, no money: for practising in test mode.',
  "Clé d'essai": 'Test key',
  'Huit caractères au moins. Ce que vous voulez : ce terminal ne parle à personne.': 'At least eight characters. Anything you like: this terminal talks to no one.',
  'Six lettres ou chiffres, par exemple ESSAI1.': 'Six letters or digits, for example ESSAI1.',
